pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor bins where the post_residual is a multiple of common item sizes (10, 20, 25).
    // Smaller post_residual values that are "clean" (e.g., 0, 10, 20) are prioritized.
    let harmonic_penalty = (post_residual % 10) as f64 * 5.0;
    score += harmonic_penalty;

    // 2. Lookahead Coupling: If next_item_size is known, penalize bins that cannot fit it.
    // This effectively implements a Best-Fit-Decreasing-like lookahead logic.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Fragmentation Mitigation: Penalize creating "micro-gaps" (1-9 space) that are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current fit is extremely poor.
    // We calibrate this by comparing the fit to the mean_residual of existing bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing bins are quite full or if we have very few options.
        if mean_residual > 20.0 && fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score += 30.0;
        }
    }

    // 5. Progression Weight: As the stream progresses, tighten the requirements (lower tolerance for dead space).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for leaving "fragmented" space (small gaps 1..10 are hard to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If a future item exists, prioritize bins that can accommodate it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that will be too small for the immediate future item
            score += 15.0;
        } else {
            // Reward bins that maintain enough space for the next item
            score -= 5.0;
        }
    }

    // Dynamic thresholding based on stream progression
    // Towards the end of the stream, prioritize aggressive packing to close bins
    if progress > 0.8 {
        if post_residual == 0 {
            score -= 20.0; // Strong incentive to complete bins
        }
    }

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no other bins can fit the item or the current bin is inefficient
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 10.0; // Force-open a new bin if nothing else fits
        } else {
            // Otherwise, make opening a new bin expensive
            score = 50.0 + (mean_residual * 0.5);
        }
    } else {
        // Global state heuristic: discourage creating too many open bins
        // If we have many open bins, prioritize filling the one with the smallest residual
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual to keep bins tight.
    // Penalty for leaving large gaps.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead matching: If post_residual is close to next_item_size, we reward it.
    // This creates "perfect" pairings.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 1.5;
    }

    // 3. Prevent opening new bins prematurely:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless fitting_bins_count is 0 (forced).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 85.0;
    }

    // 4. Global balance: If the current bin is significantly emptier than the mean, 
    // it's a good candidate to fill up to keep the "mean_residual" balanced.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Last chance protection:
    // If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progression scaling:
    // As we approach the end of the stream, prioritize closing existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor smaller post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": Gaps between 1 and 9 are often unusable
    // given the item size range (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Dynamic pressure: If few bins are open, we are more conservative. 
    // If many bins are open, we prioritize filling them to reduce fragmentation.
    score += (open_bins_count as f64) * 2.5;

    // Lookahead: If the next item is large, avoid leaving a tiny residual in the current bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // New Bin Logic: Discourage opening a new bin unless the fit is truly terrible
    // or we are near the end of the stream where consolidation matters less.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 45.0 + (progress * 10.0);

        // If we have open bins that could fit the item, penalize opening a new one heavily
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Fragmentation control: Favor bins that stay near the global mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}
